<?php $statusLabels=['open'=>'Offen','waiting_admin'=>'Wartet auf Antwort','waiting_seller'=>'Antwort von dir erforderlich','closed'=>'Geschlossen'];$senderLabels=['seller'=>'Du','admin'=>'Support','guest'=>'Du','system'=>'System'];?>
<main class="section narrow">
<div class="seller-hero"><div><span class="eyebrow"><?=App\Core\View::e($ticket['ticket_number'])?></span><h1><?=App\Core\View::e($ticket['subject'])?></h1><p>Aktueller Status: <?=App\Core\View::e($statusLabels[$ticket['status']]??$ticket['status'])?></p></div><a class="btn ghost" href="/konto/support">Zurück</a></div>
<section class="card chat"><div class="chat-log"><?php foreach($messages as $m):?><div class="message <?=$m['sender_type']==='admin'?'admin':'seller'?>"><small><?=App\Core\View::e($senderLabels[$m['sender_type']]??$m['sender_type'])?> · <?=date('d.m.Y H:i',strtotime($m['created_at']))?></small><p><?=nl2br(App\Core\View::e($m['message']))?></p></div><?php endforeach;?></div>
<?php if($ticket['status']!=='closed'):?><form method="post" class="chat-form"><?=App\Core\Csrf::field()?><textarea name="message" rows="4" required placeholder="Deine Antwort an den Support"></textarea><button class="btn primary">Antwort senden</button></form><?php else:?><div class="notice">Dieses Ticket ist abgeschlossen und kann nicht mehr beantwortet werden.</div><?php endif;?></section>
